class Solution {
  public int minMaxDifference(int num) {
    String value = Integer.toString(num);
    char replaceMax = 0;
    for (int i = 0; i < value.length(); i++)
      if (value.charAt(i) != '9') {
        replaceMax = value.charAt(i);
        break;
      }
    char replaceMin = value.charAt(0);
    long maximum = Long.parseLong(value.replace(replaceMax, '9'));
    long minimum = Long.parseLong(value.replace(replaceMin, '0'));
    return (int) (maximum - minimum);
  }
}
